#!/usr/bin/env node
/**
 * The smoke bundle (prompt 51): `backend_developer_guidelines/smoke/` — the API
 * smoke test with everything it needs and nothing to install, so the Laravel
 * developer runs the walk this repository runs, from the package alone.
 *
 *   npm run generate:smoke-bundle     # generate:backend-guidelines runs it too
 *
 * `scripts/smoke-api.js` requires the endpoint registry, the write schemas, the
 * enums and the sample-body fixtures, and they are plain CommonJS with no
 * package behind them. The bundle copies exactly the files Node loads for them
 * — read from `require.cache` in a child process, not guessed from the text —
 * under `lib/`, each at its repository path so its own relative `require`s
 * still resolve, and points the entry point's three `require`s at `./lib/…`.
 * A file that needs a package is an error: the bundle promises no install.
 *
 * The output is deterministic, so a second run changes nothing, and
 * `check:guidelines` compares the package's copy with {@link bundleFiles}.
 */

const { execFileSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const OUT = path.join(ROOT, 'backend_developer_guidelines', 'smoke');

/** The smoke test, relative to the repository. */
const ENTRY = 'scripts/smoke-api.js';

/** The Node the bundle needs: `fetch`, `AbortSignal.timeout`, `Array.prototype.at`. */
const NODE_ENGINE = '>=20';

const posix = (file) => file.split(path.sep).join('/');

/**
 * The entry point's own `require`s of repository files: `[specifier, file]`,
 * the file relative to the repository.
 *
 * @param {string} source the entry point's text
 * @returns {Array<[string, string]>}
 */
function entryRequires(source) {
  const found = [];
  for (const match of source.matchAll(/\brequire\((['"])(\.{1,2}\/[^'"]+)\1\)/g)) {
    const specifier = match[2];
    const resolved = require.resolve(path.resolve(ROOT, path.dirname(ENTRY), specifier));
    found.push([specifier, posix(path.relative(ROOT, resolved))]);
  }
  return found;
}

/**
 * Every repository file Node loads for the entry point's dependencies.
 *
 * @param {string[]} files relative to the repository
 * @returns {string[]} relative to the repository, sorted
 */
function loadedFiles(files) {
  const script = [
    `for (const file of ${JSON.stringify(files.map((file) => `./${file}`))}) require(file);`,
    'process.stdout.write(JSON.stringify(Object.keys(require.cache)));',
  ].join('\n');
  const loaded = JSON.parse(execFileSync(process.execPath, ['-e', script], { cwd: ROOT }));

  const outside = loaded.filter(
    (file) =>
      !file.startsWith(`${ROOT}${path.sep}`) || file.includes(`${path.sep}node_modules${path.sep}`)
  );
  if (outside.length > 0) {
    throw new Error(
      `The smoke test would need an install: it loads ${outside
        .map((file) => path.relative(ROOT, file))
        .join(', ')}. Keep scripts/smoke-api.js and what it requires free of packages.`
    );
  }

  return loaded
    .filter((file) => file !== '[eval]')
    .map((file) => posix(path.relative(ROOT, file)))
    .sort();
}

/** The line every copied file starts with (after a shebang). */
const banner = (source) =>
  `// Generated by \`npm run generate:smoke-bundle\` from ${source} — do not edit; edit the source and regenerate.\n`;

/** A file's text with the banner after its shebang, if it has one. */
function withBanner(text, source) {
  if (text.startsWith('#!')) {
    const end = text.indexOf('\n') + 1;
    return `${text.slice(0, end)}${banner(source)}${text.slice(end)}`;
  }
  return `${banner(source)}${text}`;
}

/** The bundle's `package.json`: a name, the Node it needs, no dependencies. */
function packageJson() {
  const root = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8'));
  return `${JSON.stringify(
    {
      name: 'squares-n-acres-api-smoke',
      version: root.version,
      private: true,
      description:
        'The API smoke test of the Squares N Acres website, with nothing to install (prompt 51).',
      license: 'UNLICENSED',
      engines: { node: NODE_ENGINE },
      scripts: { smoke: 'node smoke-api.js' },
    },
    null,
    2
  )}\n`;
}

/** The bundle's `README.md`. */
function readme() {
  return `# The API smoke test

The walk the website repository runs as \`npm run smoke\`, packed so that it needs
nothing but **Node 20 or later** — no \`npm install\`, no repository. It signs in
as the three roles, calls every endpoint of the registry with the smallest
request that should succeed, checks the status and the envelope, runs the
behaviour checks a status code cannot show, and deletes what it created.

Generated by \`npm run generate:smoke-bundle\` (and by
\`npm run generate:backend-guidelines\`) — do not edit these files.

## The three commands

\`\`\`bash
# 1. The local mock — the reference the API is built against
node smoke-api.js

# 2. Staging — the full walk: it creates, edits and deletes records
node smoke-api.js --baseUrl=https://staging.example/api --allow-writes

# 3. Production — the read checks, signed in as a real account of each role,
#    then the comparison with the local mock (which keeps the seed's admin)
node smoke-api.js --baseUrl=<production API> --email=<admin> --password=<…> \\
  --managerEmail=<manager> --managerPassword=<…> --salesEmail=<sales> --salesPassword=<…>
node smoke-api.js --baseUrl=<production API> --email=<admin> --password=<…> \\
  --compare=http://localhost:4000/api --compareEmail=admin@squaresnacres.com --comparePassword=Admin@123
\`\`\`

The production API is \`https://www.squaresnacres.com/api\` when the site and the
API share one host (Layout A of \`07_DEPLOYMENT.md\`) and
\`https://api.squaresnacres.com/api\` when they do not (Layout B). In the website
repository the same run is \`npm run smoke -- <the same options>\`.

## Write safety

The walk **writes only to this machine** (\`localhost\`, \`127.*\`, \`[::1]\`)
unless \`--allow-writes\` is passed — which is for staging. Against any other host
it runs the read-only subset: every \`GET\` of the registry except
\`redirects.resolve\` (it counts a hit), signing in and out, and the checks that
only read; under the table it names what it left out and why. \`--read-only\`
asks for that subset on this machine too.

**Production only ever gets the read checks and \`--compare\`.** The full walk and
the Postman collection run against staging.

## Options

| Option | Default | |
| --- | --- | --- |
| \`--baseUrl\` | \`http://localhost:4000/api\` | the API, \`/api\` included |
| \`--email\`, \`--password\` | the seed's admin | the admin the run signs in as |
| \`--managerEmail\`, \`--managerPassword\`, \`--salesEmail\`, \`--salesPassword\` | the seed's | the other two roles |
| \`--allow-writes\` | off | run the full walk against a host that is not this machine (staging) |
| \`--read-only\` | off | run the read-only subset even on this machine |
| \`--compare=<url>\` | — | send every read to both servers and print only the differences of shape |
| \`--compareEmail\`, \`--comparePassword\` | \`--email\`, \`--password\` | the compared server's admin, once passwords were rotated |
| \`--verbose\` | off | print every request, and every entry a read-only run left out |

It exits 1 when a check fails or a comparison differs, so it can gate a deploy.
`;
}

/**
 * Every file of the bundle, keyed by its path inside `smoke/`.
 *
 * @returns {Map<string, string>}
 */
function bundleFiles() {
  const entrySource = fs.readFileSync(path.join(ROOT, ENTRY), 'utf8');
  const direct = entryRequires(entrySource);
  const files = loadedFiles(direct.map(([, file]) => file));

  let entry = entrySource;
  for (const [specifier, file] of direct) {
    entry = entry.replace(`require('${specifier}')`, `require('./lib/${file}')`);
  }

  const bundle = new Map();
  bundle.set('package.json', packageJson());
  bundle.set('README.md', readme());
  bundle.set('smoke-api.js', withBanner(entry, ENTRY));
  for (const file of files) {
    bundle.set(`lib/${file}`, withBanner(fs.readFileSync(path.join(ROOT, file), 'utf8'), file));
  }
  return bundle;
}

/**
 * Writes the bundle, replacing whatever was there.
 *
 * @param {string} [directory] where to write it — the package's `smoke/` by default
 * @returns {string[]} the files written, relative to the directory
 */
function writeBundle(directory = OUT) {
  const files = bundleFiles();
  fs.rmSync(directory, { recursive: true, force: true });
  for (const [name, contents] of files) {
    const target = path.join(directory, name);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, contents, 'utf8');
  }
  fs.chmodSync(path.join(directory, 'smoke-api.js'), 0o755);
  return [...files.keys()].sort();
}

if (require.main === module) {
  const written = writeBundle();
  console.log(
    `smoke bundle: ${written.length} files in ${path.relative(ROOT, OUT)}/ — run \`node smoke-api.js\` there.`
  );
}

module.exports = { ENTRY, NODE_ENGINE, OUT, bundleFiles, writeBundle };
